tool.command:
export LC_ALL=C;
## dDocent_filters derives a dozen intermediate file names from its two positional ## arguments, so both the input and the output prefix are pinned to short names in ## the working directory. cp '$vcf' input.vcf;
## Argument 5 switches to a manual cutoff only when it is literally "yes"; ## argument 6 is then the cutoff itself and argument 3/4 are "yes"/"no" answers. ## All of them are given, so the prompts of the script are not reached; stdin is ## closed because the gnuplot histograms end with 'pause -1', which otherwise ## waits for a keypress instead of returning at the end of the input. dDocent_filters input.vcf out '$overlapping' '$mixed_libraries' #if $depth_cutoff.cutoff_mode == 'manual' yes '$depth_cutoff.max_mean_depth' #else no #end if < /dev/null;
## the script happily hands back a header-only VCF when the data sit outside the ## filter ranges, which looks like success but is useless [ "\$(grep -vc '^#' out.FIL.recode.vcf 2>/dev/null)" -gt 0 ] || { echo "ERROR: the filters removed every site - check that the input is an unfiltered FreeBayes VCF from dDocent and that the read layout answers are right." >&2; exit 1; };
cp out.FIL.recode.vcf '$filtered_vcf' && cp out.filterstats '$filterstats'
